/*!
 * wega-music-endless5.js - ENDLESS add-on for the Wega's Challenge music pack.
 * The game loads it by itself when an ENDLESS run needs it (it is not in index.html): it registers a lazy
 * "endless5" track with WegaMusic, decoded only while it plays. The music changes every 10 floors
 * (Endless, then Endless 1-5); the shop between floors has its own theme.
 * ENDLESS 5 (floors 51-60) - supplied by the player. Loops with a crossfade from 97.0 s (where its reverb tail starts) back to the top.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-endless5.js] load wega-music.js first"); return; }
  D.endless5 = {
    title: "ENDLESS 5 (floors 51-60)",
    credit: "supplied by the player",
    duration: 103.079,
    loopStart: 0.0,
    loopEnd: 97.0,
    xfade: 2.5,
    gain: 0.83,
    lazy: true,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("endless5") < 0) W.tracks.push("endless5");
  if (W.onPack) W.onPack("endless5");
})(typeof window !== "undefined" ? window : globalThis);
